/**
 * Process-wide fan-out for source-file change notifications.
 *
 * The dev server (via a builder change-detection adapter) calls
 * {@link notifySourceFileChange} whenever a watched source file is added,
 * changed, or removed. Interested consumers — such as the review addon, which
 * needs to mark a cached review stale when the code it describes moves on —
 * register with {@link subscribeToSourceFileChanges} and get an unsubscribe
 * handle back.
 *
 * A single module-level registry is intentional: the dev server is long-lived
 * and there is exactly one detector per process, so listeners live for the
 * lifetime of the server unless they unsubscribe.
 */

export type SourceFileChangeListener = (event: FileChangeEvent) => void;

const listeners = new Set<SourceFileChangeListener>();

/**
 * Register a listener for source-file change events.
 *
 * @returns an unsubscribe function that removes the listener so it receives no
 *   further events.
 */
export function subscribeToSourceFileChanges(listener: SourceFileChangeListener): () => void {
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}

/**
 * Deliver a change event to every registered listener.
 *
 * Iterates over a snapshot so a listener that (un)subscribes during dispatch
 * cannot mutate the set mid-iteration. A listener that throws is isolated: the
 * error is swallowed so it neither aborts the remaining listeners nor
 * propagates out of the notifier.
 */
export function notifySourceFileChange(event: FileChangeEvent): void {
  for (const listener of [...listeners]) {
    try {
      listener(event);
    } catch {
      // A misbehaving listener must not prevent the others from being notified.
    }
  }
}

/** Test-only: drop all listeners so no events are delivered after reset. */
export function internal_resetSourceFileChangeListeners(): void {
  listeners.clear();
}
